let hskDict = {};
let hskWordDict = {};
hsk.forEach((level, i) => {
    for (let word of level) {
        hskWordDict[word] = i + 1;
        for (let char of word) {
            if (hskDict[char]) continue;
            hskDict[char] = (i + 1);
        }
    }
});

function hasCharacterText(text) {
    // https://stackoverflow.com/questions/21109011/javascript-unicode-string-chinese-character-but-no-punctuation
    return /([\u4E00-\u9FCC\u3400-\u4DB5\uFA0E\uFA0F\uFA11\uFA13\uFA14\uFA1F\uFA21\uFA23\uFA24\uFA27-\uFA29]|[\ud840-\ud868][\udc00-\udfff]|\ud869[\udc00-\uded6\udf00-\udfff]|[\ud86a-\ud86c][\udc00-\udfff]|\ud86d[\udc00-\udf34\udf40-\udfff]|\ud86e[\udc00-\udc1d])+/.test(text);
}

function getHSKLevel(text) {
    if (hskWordDict[text]) return hskWordDict[text];
    let maxDifficulty = 0;
    for (let char of text.split("")) {
        if (!hskDict[char] && hasCharacterText(char)) {
            return 7;
        }
        if (hskDict[char] > maxDifficulty) {
            maxDifficulty = hskDict[char];
        }
    }
    return maxDifficulty;
}

